  'Bank transfer (donations)' => 'Банковский перевод (пожертвования)',
  'No IBAN entered.' => 'IBAN не введен.',
  'The payment method is disabled.' => 'Способ оплаты отключен.',
  'Bank transfer settings' => 'Настройки банковского перевода',
  'Two bank transfer methods' => 'Два способа банковского перевода',
